 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen, shapes = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q, component = deque([(r, c)]), []
            seen.add((r, c))
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            if len(component) == 4:
                min_r, max_r = min(x for x,y in component), max(x for x,y in component)
                min_c, max_c = min(y for x,y in component), max(y for x,y in component)
                if max_c-min_c == 2 and max_r-min_r == 1:
                    top = sum(x == min_r for x,y in component)
                    bottom = sum(x == max_r for x,y in component)
                    if top == 1 and bottom == 3:
                        shapes.append("up")
                    elif top == 3 and bottom == 1:
                        shapes.append("down")
    counts = {kind: shapes.count(kind) for kind in ("up", "down")}
    out = [[0]*6 for _ in range(3)]
    markers = ((0,0),(0,2),(2,0),(2,2))
    for i, (r,c) in enumerate(markers[:min(4,counts['up'])]):
        out[r][c] = 3
    for i, (r,c) in enumerate(markers[:min(4,counts['down'])]):
        out[r][c+3] = 1
    return out


